import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"AST-based inlining for substitute_param","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/notes/ast-based-inlining.md","filePath":"vendored/handl/project/notes/ast-based-inlining.md"}`),a={name:`handl/project/notes/ast-based-inlining.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="ast-based-inlining-for-substitute-param" tabindex="-1">AST-based inlining for <code>substitute_param</code> <a class="header-anchor" href="#ast-based-inlining-for-substitute-param" aria-label="Permalink to “AST-based inlining for substitute_param”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Backlog — deferred architectural improvement. Current implementation is correct for all tested cases.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p><code>substitute_param</code> in <code>lib-utils/src/fn/combinators.rs</code> performs parameter substitution for function inlining (e.g., <code>pipe</code>, <code>compose</code>) using byte-level string scanning rather than AST-based substitution.</p><h2 id="current-approach" tabindex="-1">Current approach <a class="header-anchor" href="#current-approach" aria-label="Permalink to “Current approach”">​</a></h2><p>The function walks the function body as raw bytes, tracking whether it is inside a double-quoted string with a simple <code>in_string</code> flag. When it finds a param name outside a string, bounded by non-identifier characters on both sides, it replaces it with the wrapped replacement expression.</p><p>Key mechanics:</p><ul><li><code>in_string</code> toggles on every unescaped <code>&quot;</code> byte.</li><li><code>\\\\</code> escape handling: skips the next byte (correctly handles <code>\\&quot;</code>).</li><li><code>is_ident_char</code> checks word boundaries (alphanumeric + <code>_</code>).</li><li><code>next_char_boundary</code> advances over multi-byte UTF-8 sequences.</li></ul><h2 id="limitation" tabindex="-1">Limitation <a class="header-anchor" href="#limitation" aria-label="Permalink to “Limitation”">​</a></h2><p>String-boundary detection is a byte-level heuristic, not an AST traversal:</p><ul><li>It handles <code>\\&quot;</code> escapes correctly — the only escape that affects boundary detection.</li><li>Other escapes (<code>\\n</code>, <code>\\t</code>, etc.) are passed through verbatim and do not interfere with the <code>&quot;</code> toggle, so they are fine.</li><li><strong>Theoretical risk:</strong> if a future string syntax introduced an escape that produces a literal <code>&quot;</code> (e.g., <code>\\x22</code> or <code>\\u0022</code>), the scanner would misidentify the string boundary and either skip or incorrectly substitute a param.</li></ul><h2 id="why-it-s-fine-today" tabindex="-1">Why it&#39;s fine today <a class="header-anchor" href="#why-it-s-fine-today" aria-label="Permalink to “Why it&#39;s fine today”">​</a></h2><ol><li>Param substitution only happens outside strings.</li><li>The escape handling correctly skips <code>\\&quot;</code>, which is the only escape that affects boundary detection.</li><li>Other escapes don&#39;t contain <code>&quot;</code> and don&#39;t affect the toggle.</li></ol><h2 id="deferred-fix-ast-based-substitution" tabindex="-1">Deferred fix: AST-based substitution <a class="header-anchor" href="#deferred-fix-ast-based-substitution" aria-label="Permalink to “Deferred fix: AST-based substitution”">​</a></h2><p>Parse the body into an expression tree, walk only identifier nodes, and substitute there — making string boundary detection a non-issue entirely.</p><h3 id="what-this-requires" tabindex="-1">What this requires <a class="header-anchor" href="#what-this-requires" aria-label="Permalink to “What this requires”">​</a></h3><ul><li>A parser for the handl expression grammar.</li><li>A tree-walker that identifies identifier nodes matching the param name.</li><li>Re-serialization back to a string.</li></ul><h3 id="why-it-was-deferred" tabindex="-1">Why it was deferred <a class="header-anchor" href="#why-it-was-deferred" aria-label="Permalink to “Why it was deferred”">​</a></h3><p>The byte-scanner is ~45 lines with zero parser dependencies. The AST approach would require parse → walk → serialize round-tripping, which is significantly more wiring and risks altering formatting or introducing its own bugs. The current approach is correct for all real-world inputs.</p><h3 id="when-to-revisit" tabindex="-1">When to revisit <a class="header-anchor" href="#when-to-revisit" aria-label="Permalink to “When to revisit”">​</a></h3><p>When the language introduces string escapes that can produce a literal <code>&quot;</code> character, or when the combinator functions need to handle more complex expression forms that the byte-scanner cannot reliably parse.</p><h2 id="location" tabindex="-1">Location <a class="header-anchor" href="#location" aria-label="Permalink to “Location”">​</a></h2><ul><li><code>packages/handl/crates/lib-utils/src/fn/combinators.rs</code> — <code>substitute_param</code> (lines 9–55)</li><li>Called by <code>inline_chain</code> (line 90), used by <code>pipe</code> and <code>compose</code>.</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};